#!/usr/bin/env node
// Generates biometric_proof.json: a real Groth16 proof (circuits/build zkey) for the actor-bound
// LiteSVM scenario (tests/common/actor.rs). Usage:
//   cargo test -p verdict --test biometric -- --ignored --nocapture print_fixture_inputs
//   node programs/verdict/tests/fixtures/gen_biometric_fixture.mjs <BET hex> <ROOT hex>
import { writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { buildCircuitInput, commitmentBytes, circuitMatch } from "../../../../circuits/js/biometric.mjs";
import { prove, verify, encodeGroth16Proof, terminate } from "../../../../circuits/js/groth16.mjs";
import { rng, randomUnit, perturb, quantize, bytes } from "../../../../circuits/test/fixtures.mjs";

const [betHex, rootHex] = process.argv.slice(2);
if (!betHex || !rootHex) {
  console.error("usage: gen_biometric_fixture.mjs <bet hex> <evidence_root hex>");
  process.exit(2);
}
const hex = (b) => Buffer.from(b).toString("hex");
const r = rng(4242);
const base = randomUnit(128, r);
const enrolled = quantize(base);
const observed = quantize(perturb(base, 0.9, r));
const salt = bytes(31, r);
const params = { participantIdx: 0, frame: 12, modality: 0, tauBps: 5500 };
if (!circuitMatch(enrolled, observed, params.tauBps)) throw new Error("embeddings do not match");

try {
  const input = buildCircuitInput({
    enrolled,
    salt,
    observed,
    betPubkey: Buffer.from(betHex, "hex"),
    evidenceRoot: Buffer.from(rootHex, "hex"),
    ...params,
  });
  const { proof, publicSignals } = await prove(input);
  if (!(await verify(publicSignals, proof))) throw new Error("snarkjs verify failed");
  const enc = encodeGroth16Proof(proof);
  const out = {
    note: "Generated by gen_biometric_fixture.mjs for tests/common/actor.rs (deterministic bet + evidence root).",
    bet: betHex,
    evidence_root: rootHex,
    commitment: hex(commitmentBytes(enrolled, salt)),
    participant: params.participantIdx,
    frame: params.frame,
    modality: params.modality,
    tau_bps: params.tauBps,
    proof_a: hex(enc.a),
    proof_b: hex(enc.b),
    proof_c: hex(enc.c),
    public_signals: publicSignals,
  };
  const path = resolve(dirname(fileURLToPath(import.meta.url)), "biometric_proof.json");
  writeFileSync(path, JSON.stringify(out, null, 2) + "\n");
  console.log(`wrote ${path}`);
} finally {
  await terminate();
}
